using System;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Animations;using UnityEngine.Playables;
public sealed class Socket216View:MonoBehaviour{
 [Serializable]public class Eye{public Vector3 whiteCentreHead,whiteNormalHead,irisCentreEye,expectedRestChildHead;public Vector2 pivotP0;public int eyeBone,owner;}
 public Hair210R2View pose;public MeshFilter backing;public Material faceSkin;public SkinnedMeshRenderer registered,other;public ComputeShader compositor;public Texture2D templateRGBA,templateRole;public Eye[]eyes;public float sourceFrame,phaseX,phaseY;public bool playing;public float speed=.25f;public RenderTexture Colour,Owner,Intrinsic,Audit;public int renderedFrame=-1;public Vector2Int delta;public Vector2[]desiredAnchors;RenderPipelineAsset oldG,oldQ;float elapsed;bool started;PlayableGraph graph;AnimationClipPlayable playable;
 public void SetState(float f,float x,float y){sourceFrame=f;phaseX=x;phaseY=y;var a=pose.source.motion.target;if(!graph.IsValid()){pose.source.motion.Release();a.enabled=true;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;graph=PlayableGraph.Create("H216 unchanged existing walk");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);playable=AnimationClipPlayable.Create(graph,pose.source.motion.existingWalk);playable.SetApplyFootIK(false);playable.SetApplyPlayableIK(false);playable.SetSpeed(0);var o=AnimationPlayableOutput.Create(graph,"Same humanoid source",a);o.SetSourcePlayable(playable);graph.Play();}a.transform.position=pose.rootRest;playable.SetTime(pose.source.motion.existingWalk.length*(f/40f));graph.Evaluate(0);var cam=pose.source.Layers.game.actor.inheritedView.worldCamera;a.transform.position=pose.rootRest+cam.transform.right*(x/pose.source.Layers.game.ppu)-cam.transform.up*(y/pose.source.Layers.game.ppu);pose.source.Layers.game.actor.ownedUV1Mesh=pose.baselineMesh;pose.source.Layers.game.actor.Apply();CopyBlocks();}
 void CopyBlocks(){var source=pose.source.Layers.game.actor.hair;var b=new MaterialPropertyBlock();source.GetPropertyBlock(b,0);registered.SetPropertyBlock(b,0);for(int i=0;i<4;i++){b.Clear();source.GetPropertyBlock(b,i);other.SetPropertyBlock(b,i);}}
 RenderTexture Make(string n){var r=new RenderTexture(480,272,0,UnityEngine.Experimental.Rendering.GraphicsFormat.R32G32B32A32_SFloat){enableRandomWrite=true,filterMode=FilterMode.Point,name=n};r.Create();return r;}
 Vector2 Project(Vector3 w){var c=pose.source.Layers.game.actor.inheritedView.worldCamera;var p=c.projectionMatrix*c.worldToCameraMatrix*new Vector4(w.x,w.y,w.z,1);return new Vector2((p.x/p.w*.5f+.5f)*480,(.5f-p.y/p.w*.5f)*272);}
 public void Render(){CopyBlocks();pose.source.Render(true);var hair=pose.source.Layers.game.actor.hair;var H=hair.bones[18];desiredAnchors=new Vector2[2];var planes=new Vector4[2];for(int i=0;i<2;i++){var e=eyes[i];var centre=H.TransformPoint(e.whiteCentreHead);var n=H.localToWorldMatrix.inverse.transpose.MultiplyVector(e.whiteNormalHead).normalized;planes[i]=new Vector4(n.x,n.y,n.z,-Vector3.Dot(n,centre));var child=hair.bones[e.eyeBone].TransformPoint(e.irisCentreEye);var expected=H.TransformPoint(e.expectedRestChildHead);desiredAnchors[i]=Project(centre)+Project(child)-Project(expected);}var mean=(desiredAnchors[0]+desiredAnchors[1])*.5f;var reference=(eyes[0].pivotP0+eyes[1].pivotP0)*.5f;delta=new Vector2Int(Mathf.FloorToInt(mean.x-reference.x+.5f),Mathf.FloorToInt(mean.y-reference.y+.5f));
  if(!Colour){Colour=Make("H216Final");Owner=Make("H216Owner");Intrinsic=Make("H216Intrinsic");Audit=Make("H216Audit");}var cam=pose.source.Layers.game.actor.inheritedView.worldCamera;var V=cam.worldToCameraMatrix;var P=cam.projectionMatrix;var L=Matrix4x4.identity;L.SetRow(0,V.GetRow(0)*(240*P[0,0]));L.SetRow(1,V.GetRow(1)*(-136*P[1,1]));L.SetRow(2,-V.GetRow(2));L[0,3]=L[1,3]=L[2,3]=0;var inv=L.inverse;var offset=new Vector3(240+240*P[0,0]*V[0,3],136-136*P[1,1]*V[1,3],-V[2,3]);var k=compositor.FindKernel("Compose");if(!compositor.IsSupported(k))throw new Exception("H216 compute unavailable");compositor.SetInts("_Delta",delta.x,delta.y);compositor.SetVector("_Plane0",planes[0]);compositor.SetVector("_Plane1",planes[1]);compositor.SetVector("_RayBase",-inv.MultiplyVector(offset));compositor.SetVector("_RayX",inv.MultiplyVector(Vector3.right));compositor.SetVector("_RayY",inv.MultiplyVector(Vector3.up));compositor.SetVector("_RayDepth",inv.MultiplyVector(Vector3.forward));compositor.SetTexture(k,"_Reference",pose.source.Reference);compositor.SetTexture(k,"_OriginalFullMeta",Eye202Layers.Sets[9].meta.rt);compositor.SetTexture(k,"_BaseRGBA",Socket216Layers.Sets[1].rgba.rt);compositor.SetTexture(k,"_BaseMETA",Socket216Layers.Sets[1].meta.rt);compositor.SetTexture(k,"_BackingMETA",Socket216Layers.Sets[0].meta.rt);compositor.SetTexture(k,"_AllHairMETA",Eye202Layers.Sets[6].meta.rt);compositor.SetTexture(k,"_TaggedHairMETA",Socket216Layers.Sets[4].meta.rt);compositor.SetTexture(k,"_TaggedHairUV",Socket216Layers.Sets[4].uv.rt);compositor.SetTexture(k,"_OtherHairRGBA",Socket216Layers.Sets[3].rgba.rt);compositor.SetTexture(k,"_OtherHairMETA",Socket216Layers.Sets[3].meta.rt);compositor.SetTexture(k,"_BrowRGBA",Eye202Layers.Sets[7].rgba.rt);compositor.SetTexture(k,"_BrowMETA",Eye202Layers.Sets[7].meta.rt);compositor.SetTexture(k,"_TemplateRGBA",templateRGBA);compositor.SetTexture(k,"_TemplateRole",templateRole);foreach(var p in new[]{("_Colour",Colour),("_Owner",Owner),("_Intrinsic",Intrinsic),("_Audit",Audit)})compositor.SetTexture(k,p.Item1,p.Item2);compositor.Dispatch(k,60,34,1);renderedFrame=Time.frameCount;
 }
 void Start(){oldG=GraphicsSettings.defaultRenderPipeline;oldQ=QualitySettings.renderPipeline;GraphicsSettings.defaultRenderPipeline=QualitySettings.renderPipeline=pose.source.Layers.pipeline;Shader.SetGlobalFloat("_FHEnabled44",0);Shader.SetGlobalFloat("_E189Diag",0);Shader.SetGlobalFloat("_E189FieldEnabled",0);Shader.SetGlobalFloat("_E202MainHideEyes",0);Eye202Layers.Current=pose.source.Layers;Eye206R2Layers.Current=pose.source;Socket216Layers.Current=this;pose.source.Layers.game.SetPose(0);pose.source.Layers.game.Bind(true);SetState(sourceFrame,phaseX,phaseY);Socket216Stage.Install(this);started=true;}
 void Update(){if(playing){elapsed+=Time.unscaledDeltaTime*speed;float dt=pose.source.motion.existingWalk.length/40;if(elapsed>=dt){int n=Mathf.FloorToInt(elapsed/dt);elapsed-=n*dt;SetState((Mathf.FloorToInt(sourceFrame)+n)%40,0,0);}}}
 void OnGUI(){GUI.Label(new Rect(10,8,1150,42),"H215 curved socket + H213 fixed template / source whole284 strand eye-only exception / art HOLD\nActual Unity frame"+sourceFrame.ToString("F2")+" / fixed game130 reference, PPU90.50967 / skin then authored white then iris, actual depth retained");if(GUI.Button(new Rect(10,56,80,25),playing?"Pause":"Play"))playing=!playing;if(GUI.Button(new Rect(100,56,65,25),"0.25x"))speed=.25f;if(GUI.Button(new Rect(175,56,55,25),"1x"))speed=1;if(GUI.Button(new Rect(240,56,45,25),"<")){playing=false;SetState(Mathf.Max(0,sourceFrame-1),0,0);}if(GUI.Button(new Rect(295,56,45,25),">")){playing=false;SetState(Mathf.Min(40,sourceFrame+1),0,0);}if(Colour&&pose.source.Colour){GUI.DrawTexture(new Rect(10,94,480,272),pose.source.Colour,ScaleMode.StretchToFill,false);GUI.DrawTexture(new Rect(500,94,480,272),Colour,ScaleMode.StretchToFill,false);var crop=new Rect(206/480f,(272-97)/272f,25/480f,24/272f);GUI.DrawTextureWithTexCoords(new Rect(10,400,200,192),pose.source.Colour,crop,false);GUI.DrawTextureWithTexCoords(new Rect(500,400,200,192),Colour,crop,false);}}
 void OnDisable(){Socket216Stage.Remove(this);Socket216Layers.Dispose();if(graph.IsValid())graph.Destroy();Eye206R2Layers.Dispose();Eye202Layers.Dispose();if(started){GraphicsSettings.defaultRenderPipeline=oldG;QualitySettings.renderPipeline=oldQ;started=false;}foreach(var r in new[]{Colour,Owner,Intrinsic,Audit})if(r){r.Release();Destroy(r);}}
